SHIFT_THRESHOLD = 10000


# ---------------------------------------------------------
# 1. Calculate Multipliers based on the 10k Threshold
# ---------------------------------------------------------
def calculate_multipliers(dataset, threshold):
    multipliers = [1.0]  # Gear 0 is the baseline
    num_gears = len(dataset[0])

    for g in range(num_gears - 1):
        ratio = 1.0
        # Find the exact step where this gear crosses the threshold
        for i in sorted(dataset.keys()):
            raw_current = dataset[i][g]
            raw_next = dataset[i][g + 1]

            # We want to catch it when it crosses the threshold,
            # but BEFORE it hits the 65535 ADC ceiling!
            if raw_current >= threshold and raw_current < 65000:
                ratio = raw_current / raw_next
                print(f"Gear {g} -> {g + 1} Shift at Step {i}:")
                print(f"  Raw G{g}: {raw_current} / Raw G{g + 1}: {raw_next} = Ratio: {ratio:.4f}")
                break

        next_multiplier = multipliers[-1] * ratio
        multipliers.append(next_multiplier)

    print(f"\nFinal Calculated Multipliers: {[round(m, 4) for m in multipliers]}\n")
    return multipliers


multipliers = calculate_multipliers(data, SHIFT_THRESHOLD)

# ---------------------------------------------------------
# 2. Determine the "Active" Gear for each step
# ---------------------------------------------------------
active_gears = {}
current_gear = 0
steps = sorted(data.keys())

for i in steps:
    # Shift up if the current gear exceeds the threshold
    while current_gear < 3 and data[i][current_gear] > SHIFT_THRESHOLD:
        current_gear += 1
    active_gears[i] = current_gear


