# ---------------------------------------------------------
# 4. Plotting Variant 2: The RELATIVE Difference / Error Plot (%)
# ---------------------------------------------------------
plt.figure(figsize=(12, 6))

for i in steps:
    if i == 0: continue  # Skip step 0 to avoid dividing by zero

    act_g = active_gears[i]
    act_val = data[i][act_g] * multipliers[act_g]

    if act_val == 0: continue  # Extra safety check for divide-by-zero

    # Error vs Lower Neighbor (Percentage)
    if act_g > 0 and data[i][act_g - 1] < 65500:
        low_val = data[i][act_g - 1] * multipliers[act_g - 1]
        perc_diff_low = ((low_val - act_val) / act_val) * 100
        plt.scatter(i, perc_diff_low, color='red', s=60,
                    label='Lower Neighbor Error (%)' if i == 2 else "")

    # Error vs Upper Neighbor (Percentage)
    if act_g < 3:
        up_val = data[i][act_g + 1] * multipliers[act_g + 1]
        perc_diff_up = ((up_val - act_val) / act_val) * 100
        plt.scatter(i, perc_diff_up, color='green', s=60,
                    label='Upper Neighbor Error (%)' if i == 1 else "")

# --- Add the Vertical Gear Shift Lines ---
shift_steps = []
for index in range(1, len(steps)):
    prev_i = steps[index - 1]
    curr_i = steps[index]
    if active_gears[curr_i] != active_gears[prev_i]:
        shift_steps.append(curr_i)

for i, shift in enumerate(shift_steps):
    plt.axvline(x=shift, color='black', linestyle='-.', alpha=0.4,
                label='Gear Shift Boundary' if i == 0 else "")

# --- Plot Formatting ---
plt.axhline(0, color='black', linewidth=1.5, linestyle='--')
plt.title("Hardware Analog Drift: Percentage Error Between Gears", fontweight='bold')
plt.xlabel("Sweep Step (i)")
plt.ylabel("Relative Difference (%)")

